REMOVE_OUTPUT_WORKFLOW_INVERSE = ((629, 328, '11cd9e875296bd66a7fe4932b8774e3152110f531eec148ab376851c3f918b67', '    # Timed-step union445min; SOURCE scopes select disjoint UI work.\n    # Preview345 / recovery339 / installed210 / dormant ARM Android267 / dormant iOS243, plus5 overhead.\n    # Android adds build9 + preparation22 + test23 + summary3;272 <=350.\n    # iOS installed-only adds build9 + test22 + summary2;248 <=350, never preview+24.\n'), (150120, 9028, '9d50426024c5a0b7935ae93ee5c06be69221dce04aff47f27c4b8a4b610cada1', ''), (159699, 296, '757619f49bf177bc5404bec36b927f406b9ca1ddc8bbc79609c4ad7981e8105d', ''), (160791, 225, 'adbb7994c243addb230dcff883b114ded25035ee8931a15b6bb6aca2238a89fd', ''), (315226, 521, 'b37eab9482c0d97fa90e1f37e948849a9b3f7d8cfc3bda939e630b8bb07a0726', ''))


def without_remove_output_workflow(source):
    source = without_shipping_compile_workflow(source)
    marker = "      - name: Prepare the fixed two-file removal package without executing it\n"
    if marker not in source:
        if "finalize-remove-package --target" in source or "finalize-remove-image --target" in source or "package-remove --target" in source:
            raise AssertionError("partial Remove output workflow")
        return source
    value = source.encode()
    for start, length, expected, prior in reversed(REMOVE_OUTPUT_WORKFLOW_INVERSE):
        actual = value[start:start + length]
        if hashlib.sha256(actual).hexdigest() != expected:
            raise AssertionError("Remove output workflow fixed region differs")
        value = value[:start] + prior.encode() + value[start + length:]
    if hashlib.sha256(value).hexdigest() != "dd0ca6b4e80d05f276a129049b9600a9e9eccbc26a881b515accceefadcafcca":
        raise AssertionError("Remove output workflow inverse changed prior source")
    return value.decode()


def workflow_evidence_paths(workflow):
    workflow = without_remove_output_workflow(workflow)
    """Project only the two fixed artifact lists as DATA, never evaluate expressions."""
    installed = "Preserve bounded originals; upload success is never GUI/native acceptance"
    aqua = "Preserve bounded original evidence; upload alone is not an Aqua pass"
    names = [name for name in (installed, aqua) if "      - name: " + name + "\n" in workflow]
    if len(names) != 1:
        raise AssertionError("expected one fixed evidence step")
    block = workflow_step(workflow, names[0])
    if block.count("          path: |\n") != 1:
        raise AssertionError("expected one literal artifact scalar")
    lines = []
    for line in block.split("          path: |\n", 1)[1].splitlines():
        if not line.startswith("            "):
            break
        lines.append(line[12:])
    scalar = "\n".join(lines) + "\n"
    root = "${{ steps.work.outputs.root }}"
    if names[0] == installed:
        opening, closing = "${{ format('", "', steps.work.outputs.root) }}\n"
        if not scalar.startswith(opening) or not scalar.endswith(closing) or len(scalar[4:-4]) > 21000:
            raise AssertionError("expected the sole bounded fixed-root format")
        template = scalar[len(opening):-len(closing)]
        lines = template.split("\n")
        if len(lines) != 314 or len(set(lines)) != 314 or any(not line.startswith("{0}/") for line in lines):
            raise AssertionError("expected the 314 fixed format rows")
        suffixes = [line[3:] for line in lines]
    else:
        if not lines or any(not line.startswith(root + "/") for line in lines):
            raise AssertionError("expected literal Aqua evidence rows")
        suffixes = [line[len(root):] for line in lines]
    for suffix in suffixes:
        if (not suffix.isascii() or any(not (character.isalnum() or character in "_./-") for character in suffix)
                or any(part in ("", ".", "..") for part in suffix[1:].split("/"))):
            raise AssertionError("expected literal artifact suffixes without globs or interpolation")
    return "".join(root + suffix + "\n" for suffix in suffixes)


def normal_app_steps(workflow):
    return tuple(workflow_step(workflow, name) for name in (
        "Build the ordinary selected-target desktop image and embedded frontend",
        "Assemble the ordinary image app and sign code inside-out (never --deep)",
        "Bind this completed signed app and current-source runtime into fresh Installer DATA"))


def entry_macho_fixture(*extra, library=b"/usr/lib/libSystem.B.dylib", target="aarch64-apple-darwin"):
    """Inert loader-policy DATA, not a compiled/signed/launched entry."""
    cpu, subtype = {"aarch64-apple-darwin": (0x0100000C, 0), "x86_64-apple-darwin": (0x01000007, 3)}[target]
    def named(command, value, prefix):
        data = value + b"\0"
        length = (prefix + len(data) + 7) // 8 * 8
        header = struct.pack("<III", command, length, prefix)
        return header + bytes(prefix - len(header)) + data + bytes(length - prefix - len(data))
    commands = (struct.pack("<6I", 0x32, 24, 1, 26 << 16, 26 << 16, 0),
                named(0xC, library, 24), named(0xE, b"/usr/lib/dyld", 12),
                struct.pack("<IIQQ", 0x80000028, 24, 0, 0), *extra)
    return struct.pack("<8I", 0xFEEDFACF, cpu, subtype, 2, len(commands),
                       sum(map(len, commands)), 0x200084, 0) + b"".join(commands)


def history_provider_macho_fixture(*extra, target="aarch64-apple-darwin", minimum=12, sdk=12,
                                   tools=0, libraries=None, load_command=0xC):
    """Tiny thin/load-command DATA only; no executable/signature/native proof."""
    cpu, subtype = {"aarch64-apple-darwin": (0x0100000C, 0), "x86_64-apple-darwin": (0x01000007, 3)}[target]
    if libraries is None:
        libraries = (b"/usr/lib/libSystem.B.dylib", b"/usr/lib/libresolv.9.dylib",
                     b"/System/Library/Frameworks/CoreFoundation.framework/Versions/A/CoreFoundation",
                     b"/System/Library/Frameworks/Security.framework/Versions/A/Security")
    def named(command, value, prefix):
        data = value + b"\0"
        length = (prefix + len(data) + 7) // 8 * 8
        header = struct.pack("<III", command, length, prefix)
        return header + bytes(prefix - len(header)) + data + bytes(length - prefix - len(data))
    commands = (struct.pack("<6I", 0x32, 24, 1, minimum << 16, sdk << 16, tools),
                named(0xE, b"/usr/lib/dyld", 12),
                *(named(load_command, name, 24) for name in libraries), *extra)
    return struct.pack("<8I", 0xFEEDFACF, cpu, subtype, 2, len(commands),
                       sum(map(len, commands)), 0, 0) + b"".join(commands)


def image_macho_fixture(role="desktop", *extra, install_name=None, library=b"/usr/lib/libSystem.B.dylib", kind=6, target="aarch64-apple-darwin"):
    """Actual MH_DYLIB-shaped inert DATA, never a renamed executable/native pass."""
    cpu, subtype = {"aarch64-apple-darwin": (0x0100000C, 0), "x86_64-apple-darwin": (0x01000007, 3)}[target]
    def named(command, value):
        data = value + b"\0"
        length = (24 + len(data) + 7) // 8 * 8
        return struct.pack("<6I", command, length, 24, 0, 0, 0) + data + bytes(length - 24 - len(data))
    identity = TOOL.IMAGE_INSTALL_NAMES[role].encode("ascii") if install_name is None else install_name
    commands = (struct.pack("<6I", 0x32, 24, 1, 26 << 16, 26 << 16, 0),
                named(0xD, identity), named(0xC, library), *extra)
    return struct.pack("<8I", 0xFEEDFACF, cpu, subtype, kind, len(commands),
                       sum(map(len, commands)), 0x84, 0) + b"".join(commands)


def packaging_fixture(target="aarch64-apple-darwin", *, package=b"synthetic completed package DATA"):
    """Public malformed-certificate-free DATA only; never a signing credential."""
    service = (b"schema=1\napp-identifier=dev.mobile-release-kit.desktop\n"
        b"helper-identifier=dev.mobile-release-kit.desktop.android-register\n"
        b"team-identifier=TEST000001\ndeveloper-id-certificate-sha1=" + b"1" * 40 + b"\n")
    profile = (b"schema=1\nstate=configured\nteam-identifier=TEST000001\nrsa-bits=2048\n"
        b"leaf-certificate-sha1=" + b"1" * 40 + b"\nleaf-certificate-sha256=" + b"2" * 64
        + b"\nissuer-certificate-sha256=" + b"3" * 64 + b"\nroot-certificate-sha256=" + b"4" * 64
        + b"\npublic-key-pkcs1-sha256=" + b"5" * 64 + b"\n")
    prefix = "macos26-arm64-" if target == TOOL.ARM_TARGET else "macos26-x86_64-"
    selection = TOOL.BuildSelection(target, "0.2.0", prefix + "packaging-data-02")
    history = {"schemaVersion": 1, "targets": {name: {"acceptedPredecessors": [], "signingPolicies": []}
               for name in TOOL.MAC_TARGETS}}
    # Independent literal declaration order matching the public PolicyWire
    # schema, not the new descriptor assembly function under test.
    policy = {"schemaVersion": 1, "kind": "mrk-macos-developer-id-code-policy-v1", "teamIdentifier": "TEST000001",
              "leafCertificateSha1": "1" * 40, "leafCertificateSha256": "2" * 64,
              "hardenedRuntime": True, "entitlements": "empty"}
    policy_sha = TOOL.digest(json.dumps(policy, separators=(",", ":")).encode("ascii"))
    current = {"profile": "fixed-macos26-arm64-maintenance-v2" if target == TOOL.ARM_TARGET else "fixed-macos26-x86_64-maintenance-v2",
        "packageIdentifier": TOOL.PACKAGE_ID, "bundleIdentifier": TOOL.BUNDLE_ID,
        "packageVersion": selection.package_version, "release": selection.release, "sourceCommit": "a" * 40,
        "protocolSha256": TOOL.CURRENT_PROTOCOL, "runtimeManifestSha256": "c" * 64, "inventorySha256": "d" * 64,
        "signingPolicySha256": policy_sha, "packageSha256": TOOL.digest(package)}
    descriptor = {"schemaVersion": 2, "kind": "mrk-macos-install-producer-v2", "domain": "MobileReleaseKit-package-producer-v2",
        "target": target, "releaseSet": {"schemaVersion": 2, "current": current, "acceptedPredecessors": []},
        "signingPolicies": [{"sha256": policy_sha, "policy": policy}]}
    return profile, service, selection, history, descriptor


@unittest.skipUnless(ANDROID_HELPER is not None, "POSIX inert packaging DATA only")
class MacAndroidHelperPackagingData(unittest.TestCase):
    """No compiler/codesign/helper/owner execution; every child is a DATA double."""

    def test_removal_target_routes_keep_preparation_scripts_and_observers_bound(self):
        module = ANDROID_HELPER
        for target in TOOL.MAC_TARGETS:
            other = TOOL.INTEL_TARGET if target == TOOL.ARM_TARGET else TOOL.ARM_TARGET
            profile, service, selection, history, descriptor = packaging_fixture(target, package=b"xar!inert")
            binding = dict(sourceCommit="a" * 40, target=target, release=selection.release,
                inventorySha256="b" * 64, packageSha256="c" * 64,
                removeDescriptorSha256="d" * 64, removeSignatureSha256="e" * 64)
            self.assertIs(TOOL.removal_fixture_binding_data(binding, selection=selection), binding)
            with self.assertRaises(TOOL.Refused):
                TOOL.removal_fixture_binding_data(dict(binding, target=other), selection=selection)
            for case in ("ordinary", "abrupt"):
                environment = dict(GITHUB_REF=module.REMOVAL_REF, MRK_MACOS_PACKAGE_ROLE="ordinary-image",
                    MRK_MACOS_REMOVAL_CASE=case, MRK_MACOS_REMOVAL_CORRELATION="f" * 32,
                    GITHUB_SHA="a" * 40, GITHUB_RUN_ID="123", GITHUB_RUN_ATTEMPT="1")
                self.assertEqual(module.removal_context_data(environment, target), (case, "f" * 32))
                for changes in (dict(GITHUB_REF="refs/heads/main"), dict(MRK_MACOS_PACKAGE_ROLE="observer"),
                                dict(MRK_MACOS_REMOVAL_CASE="other"), dict(MRK_MACOS_REMOVAL_CORRELATION="0" * 32)):
                    with self.assertRaises(module.Refused): module.removal_context_data(dict(environment, **changes), target)
                with self.assertRaises(module.Refused): module.removal_context_data(environment, "other")
                prepared = dict(schemaVersion=1, phase="prepare-removal-observers", source="a" * 40,
                    workflowSource="a" * 40, target=target, runId="123", runAttempt="1", case=case,
                    correlation="f" * 32, passed=True, targetRetired=True, originalClosesKnown=True,
                    outerFinalityRequired=True, nativeCalls=46, nativeCallsSha256="b" * 64,
                    credentialCalls=158, credentialCallsSha256="c" * 64, credentialContexts=8,
                    targetBinding=binding, targetFiles={}, targetImage={}, observerImage={}, observers={},
                    observerProgramSha256="d" * 64, controlBytes=1024, productReady=False)
                self.assertIs(module.removal_prepared_data(prepared, environment, target, case, "f" * 32), prepared)
                for changes in (dict(target=other), dict(source="b" * 40), dict(originalClosesKnown=False),
                                dict(case="abrupt" if case == "ordinary" else "ordinary"), dict(nativeCalls=45)):
                    with self.assertRaises(module.Refused):
                        module.removal_prepared_data(dict(prepared, **changes), environment, target, case, "f" * 32)
            # Real small filesystem reads/copies and actual Mach-O DATA parser;
            # bytes are never executed or signed. Only the source selection is supplied.
            program = entry_macho_fixture(target=target)
            real_stat, real_fstat = os.stat, os.fstat
            def flags(info):
                # Linux has no st_flags: this port supplies only Darwin's
                # observed-zero field; mode/identity/read/POST/close remain real.
                values = {key: getattr(info, key) for key in dir(info) if key.startswith("st_")}
                values["st_flags"] = 0
                return SimpleNamespace(**values)
            def named(*args, **kwargs): return flags(real_stat(*args, **kwargs))
            def held(*args, **kwargs): return flags(real_fstat(*args, **kwargs))
            for role in ("abrupt", "observer-before"):
                with tempfile.TemporaryDirectory() as temporary:
                    root = Path(temporary); original = root / "input"; original.write_bytes(program); original.chmod(0o555)
                    args = SimpleNamespace(target=target, role=role, remover=original, expected_remover=TOOL.digest(program),
                        output=root / "scripts", correlation=None if role == "abrupt" else "f" * 32,
                        target_binding=None if role == "abrupt" else binding)
                    with mock.patch.object(TOOL, "source_build_selection", return_value=selection), mock.patch.object(os, "stat", side_effect=named), mock.patch.object(os, "fstat", side_effect=held):
                        result = TOOL.removal_fixture_scripts_command(args)
                    self.assertEqual(result["removerSha256"], TOOL.digest(program))
                    self.assertEqual((args.output / TOOL.REMOVER_NAME).read_bytes(), program)
                    self.assertEqual(original.read_bytes(), program)
                    original.chmod(0o600); original.write_bytes(entry_macho_fixture(target=other)); original.chmod(0o555)
                    args.expected_remover = TOOL.digest(original.read_bytes()); args.output = root / "wrong"
                    with mock.patch.object(TOOL, "source_build_selection", return_value=selection), mock.patch.object(os, "stat", side_effect=named), mock.patch.object(os, "fstat", side_effect=held), self.assertRaises(TOOL.Refused):
                        TOOL.removal_fixture_scripts_command(args)
                    self.assertFalse(args.output.exists())
            # The observer retains the real installed lineage but signs different
            # own code. Both byte/target checks run through the ordinary parser.
            _, inventory, _, _ = installation_record_fixture(selection=selection)
            inventory = json.loads(inventory)
            inventory["files"].append(dict(path="app/" + TOOL.REMOVER, size=len(program),
                sha256=TOOL.digest(program), executable=True))
            inventory["files"].sort(key=lambda row: row["path"]); inventory = TOOL.canonical(inventory)
            descriptor["releaseSet"]["current"]["inventorySha256"] = TOOL.digest(inventory)
            source = TOOL.ProducerSelection("TEST000001", "1" * 40, "2" * 64, 2048, "3" * 64, "4" * 64)
            own = program + b"different inert observer DATA"
            arguments = (TOOL.canonical(descriptor), inventory, program, own, b"xar!inert", source, selection)
            emitted = TOOL.packaging_observer_descriptor_data(*arguments, source_commit="a" * 40, manifest="c" * 64)
            self.assertEqual(json.loads(emitted)["target"], target)
            self.assertEqual(json.loads(emitted)["removerExecutableSha256"], TOOL.digest(own))
            for wrong in (program, entry_macho_fixture(target=other)):
                with self.assertRaises(TOOL.Refused):
                    TOOL.packaging_observer_descriptor_data(*arguments[:3], wrong, *arguments[4:], source_commit="a" * 40, manifest="c" * 64)

    def test_removal_ui_caller_routes_both_targets_into_actual_context(self):
        module = ANDROID_HELPER
        path = Path(__file__).absolute().parents[2] / "desktop/tools/macos_normal_ui_runner.py"
        spec = importlib.util.spec_from_file_location("removal_actual_context_data", path)
        normal = importlib.util.module_from_spec(spec); spec.loader.exec_module(normal)
        resource = SimpleNamespace(RLIMIT_FSIZE=1, getrlimit=lambda _: (1073741824, 1073741824))
        for target, machine, hosted in ((TOOL.ARM_TARGET, "arm64", "github-hosted-macos26-arm64"),
                                       (TOOL.INTEL_TARGET, "x86_64", "github-hosted-macos26-x86_64")):
            for case in ("ordinary", "abrupt"):
                called = []
                operation = object.__new__(module.Operation)
                operation.target = target; operation.removal_case = case
                operation.work = Path("/Users/runner/work/_temp/mrk-macos-installed.ABCDef12")
                operation.checkout = Path("/Users/runner/work/mobile-release-kit/mobile-release-kit")
                operation.image_source = "a" * 40; operation.removal_correlation = "f" * 32
                operation.owner = SimpleNamespace(); operation.removal_runner = normal
                operation.removal_resource = resource; operation.removal_thread = None
                operation.removal_ui_outcome = {"done": False, "known": False}
                operation.removal_ui_lock = contextlib.nullcontext()
                class InlineThread:
                    # Scheduling is the only substituted worker boundary: no
                    # thread/native process is started by this DATA fixture.
                    def __init__(self, *, target, name, daemon):
                        self.callback = target
                        self.name, self.daemon = name, daemon
                    def start(self): self.callback()
                operation.removal_threading = SimpleNamespace(Thread=InlineThread)
                def admitted(phase, **options):
                    selected, result = normal.removal_phase_context(phase, **options)
                    self.assertEqual(phase.environment["TEST_RUNNER_MRK_NORMAL_UI_HOSTED_JOB"], hosted)
                    self.assertEqual(options["target"], target)
                    self.assertEqual(phase.clock.containing_deadline_ns, 500_000_000_000)
                    self.assertIs(phase.owner, operation.owner)
                    called.append((selected, result.name))
                    return CompletedProcess([], 0, b"", b""), {"case": case}
                with mock.patch.object(normal.sys, "platform", "darwin"), mock.patch.object(normal.platform, "machine", return_value=machine), \
                     mock.patch.object(normal.platform, "mac_ver", return_value=("26.6", (), "")), \
                     mock.patch.object(normal, "_removal_resource", resource), mock.patch.object(normal.time, "monotonic_ns", return_value=0), \
                     mock.patch.object(normal, "execute_removal_ui_phase", side_effect=admitted):
                    operation.removal_ui_start(500_000_000_000)
                self.assertEqual(called, [(normal.CLASS + normal.REMOVAL_METHODS[case], "removal-" + case + "-test.xcresult")])
                self.assertEqual(operation.removal_ui_outcome["done"], True)
                self.assertEqual(operation.removal_ui_outcome["known"], True)
                self.assertEqual(operation.removal_thread.name, "mrk-fixed-removal-ui")
                self.assertFalse(operation.removal_thread.daemon)
                self.assertTrue(operation.removal_ui_entered)

    def test_current_removal_matrix_keeps_each_target_and_case_isolated(self):
        source = (Path(__file__).absolute().parents[2] / ".github/workflows/desktop-macos-installed.yml").read_text()
        match = re.search(r"include: \$\{\{ fromJSON\(github.ref == 'refs/heads/verify/desktop-macos-removal-lifecycle' && '([^']+)' \|\| '([^']+)'\) \}\}", source)
        self.assertIsNotNone(match)
        selected, ordinary = map(json.loads, match.groups())
        selected_targets = {row["target"] for row in selected}
        self.assertTrue(selected_targets and selected_targets <= set(TOOL.MAC_TARGETS))
        self.assertEqual(selected, [dict(row, removal_case=case) for case in ("ordinary", "abrupt")
                                   for row in ordinary if row["target"] in selected_targets])
        self.assertEqual([(row["target"], row["runner"], row["machine"], row["hosted_job"]) for row in ordinary],
            [(TOOL.ARM_TARGET, "macos-26", "arm64", "github-hosted-macos26-arm64"),
             (TOOL.INTEL_TARGET, "macos-26-intel", "x86_64", "github-hosted-macos26-x86_64")])
        self.assertEqual(len(selected), 2 * len(selected_targets))
        self.assertIn("      fail-fast: false\n      max-parallel: 2\n      matrix:", source)
        # Execute the real workflow admission branch, not just a matching matrix.
        # The version probes and other workflow commands are never executed.
        step = workflow_step(source, "Reserve fresh work and record exact source and actual tool bindings")
        body = step.split("<<'PY'\n", 1)[1].split("\n          PY\n", 1)[0]
        tree = ast.parse("\n".join(line[10:] for line in body.splitlines()))
        routes = next(node for node in tree.body if isinstance(node, ast.Assign)
                      and isinstance(node.targets[0], ast.Name) and node.targets[0].id == "supplier_routes")
        guards = [node for node in tree.body if isinstance(node, ast.If) and isinstance(node.test, ast.Compare)
                  and any(isinstance(value, ast.Constant) and value.value == ANDROID_HELPER.REMOVAL_REF
                          for value in node.test.comparators)]
        self.assertEqual(len(guards), 1)
        program = compile(ast.Module(body=guards, type_ignores=[]), "<removal-source-admission>", "exec")
        with tempfile.TemporaryDirectory() as temporary:
            environment_file = Path(temporary) / "environment"
            for target, case in [(target, case) for target in TOOL.MAC_TARGETS for case in ("ordinary", "abrupt")] + [("other", "ordinary"), (TOOL.INTEL_TARGET, "other")]:
                environment_file.write_text("")
                environment = {"GITHUB_REF": ANDROID_HELPER.REMOVAL_REF, "MRK_MACOS_REMOVAL_CASE": case,
                               "GITHUB_ENV": str(environment_file)}
                value = {"target": target}
                context = {"build_target": target, "supplier_routes": ast.literal_eval(routes.value), "value": value,
                           "os": SimpleNamespace(environ=environment, urandom=lambda count: b"a" * count)}
                if target not in TOOL.MAC_TARGETS or case not in ("ordinary", "abrupt"):
                    with self.assertRaisesRegex(ValueError, "removal fixed source case"):
                        exec(program, context)
                    self.assertEqual(environment_file.read_text(), "")
                    self.assertEqual(value, {"target": target})
                    continue
                exec(program, context)
                self.assertEqual(value["removalCase"], case)
                self.assertEqual(value["instrumented"], case == "abrupt")
                self.assertEqual(value["removalCorrelation"], "61" * 16)
                self.assertEqual(environment_file.read_text(), "MRK_MACOS_REMOVAL_CORRELATION=" + "61" * 16 + "\n")
                self.assertTrue(all(value[key] is False for key in ("applicationLaunched", "fullUIQualified",
                    "removalQualified", "powerLossQualified", "distributionQualified")))

        # Run only the observer-preparation target/correlation predicate, never
        # the privileged observation owner or the rest of its workflow step.
        import subprocess
        step = workflow_step(source, "Prepare three source-bound readonly observation carriers without removal")
        predicates = [line.strip() for line in step.splitlines()
                      if line.strip().startswith('[[ "$MRK_MACOS_TARGET"') or line.strip().startswith('[[ ( "$MRK_MACOS_TARGET"')]
        self.assertEqual(len(predicates), 1)
        for target, correlation, accepted in [(target, "f" * 32, True) for target in TOOL.MAC_TARGETS] + [
            ("other", "f" * 32, False), (TOOL.INTEL_TARGET, "bad", False), (TOOL.ARM_TARGET, "F" * 32, False)]:
            result = subprocess.run(["/usr/bin/bash", "-c", predicates[0]], check=False,
                env={"MRK_MACOS_TARGET": target, "MRK_MACOS_REMOVAL_CORRELATION": correlation},
                stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=5)
            self.assertEqual(result.returncode == 0, accepted)
            self.assertEqual(result.stdout, b"")
            self.assertEqual(result.stderr, b"")

    def test_primary_owner_finality_failure_data_is_closed_bounded_and_private(self):
        module = ANDROID_HELPER
        class ProcessErrorData(RuntimeError):
            def __str__(self):
                raise AssertionError("error text must not be rendered")
        class Foreign(ProcessErrorData):
            @property
            def owner_finality_diagnostic(self):
                raise AssertionError("foreign attributes must not be consulted")
        owner = SimpleNamespace(ProcessError=ProcessErrorData)
        checkout = Path("/public-synthetic-checkout")
        def emit(observed):
            error = ProcessErrorData("owned command exceeded its original deadline")
            error.owner_finality_diagnostic = observed
            result = module.original_failure(error, owner, checkout, 720, 2147483647)
            self.assertEqual(result["classification"], "deadline")
            self.assertNotIn("contained", result)
            self.assertNotIn("cleanup_complete", result)
            return result
        for observation in ((1, 0, 1023, 15, None), (1, 1, 0, 0, 0),
                            (1, 1, (1 << 3) | (1 << 7) | (1 << 10), 15, None),
                            *((1, 1, 0, 0, mask) for mask in (32, *range(48, 64)))):
            self.assertEqual(emit(observation)["ownerFinality"], list(observation))
        for invalid in (None, "PRIVATE_SENTINEL", {}, [], (1,), (True, 1, 0, 0, 0),
                        (1, True, 0, 0, None), (1, 1, False, 0, None), (1, 1, 0, False, None),
                        (2, 1, 0, 0, None), (1, 2, 0, 0, None), (1, 0, 1024, 0, None),
                        (1, 1, 1048576, 0, None), (1, 1, -1, 0, None), (1, 1, 0, 16, None),
                        (1, 1, 0, -1, None), (1, 0, 0, 0, 0), (1, 1, 0, 0, True),
                        (1, 1, 0, 0, 1), (1, 1, 0, 0, 47), (1, 1, 0, 0, 64),
                        (1, 1, 0, 0, "PRIVATE_SENTINEL")):
            result = emit(invalid)
            self.assertIsNone(result["ownerFinality"])
            self.assertNotIn("PRIVATE_SENTINEL", json.dumps(result))
        for error in (ProcessErrorData("unclassified"), Foreign("PRIVATE_SENTINEL"), RuntimeError("PRIVATE_SENTINEL")):
            result = module.original_failure(error, owner, checkout, 720, 1024)
            self.assertIsNone(result["ownerFinality"])
            self.assertNotIn("PRIVATE_SENTINEL", json.dumps(result))
        # Maximal admitted retained frame names/counts plus diagnostic bounds.
        def template(depth, recurse, error):
            if depth:
                return recurse(depth - 1, recurse, error)
            raise error
        code = template.__code__.replace(co_filename=str(checkout / "src/mobile_release/_command_process.py"),
                                         co_name="x" * 64, co_firstlineno=999990)
        recurse = FunctionType(code, {})
        error = ProcessErrorData("owned command exceeded its original deadline")
        error.owner_finality_diagnostic = (1, 1, 1048575, 15, 63)
        try:
            recurse(30, recurse, error)
        except ProcessErrorData as caught:
            result = module.original_failure(caught, owner, checkout, 2147483647, 2147483647)
        self.assertEqual(len(result["frames"]), 8)
        self.assertEqual(result["ownerFinality"], [1, 1, 1048575, 15, 63])
        self.assertLessEqual(len(json.dumps(result, sort_keys=True, separators=(",", ":")).encode("ascii")), 2048)
        helper_body = (Path(__file__).absolute().parents[2] / "desktop/tools/macos_android_helper_package.py").read_bytes()
        source_cap = module.HELPER_SOURCE_BYTES
        self.assertIs(type(source_cap), int)
        self.assertEqual(source_cap, 1024 * 1024)
        self.assertGreater(len(helper_body), 0)
        self.assertLessEqual(len(helper_body), source_cap)
        # Actual no-follow regular-file originals: complete read and consuming
        # close for current SOURCE and at the ceiling; +1 refuses before read.
        with tempfile.TemporaryDirectory(prefix="mrk-producer-source-cap-") as temporary:
            root = Path(temporary); root.chmod(0o700)
            tools = root / "desktop/tools"; tools.mkdir(parents=True, mode=0o700)
            at_cap = helper_body + b"\n" * (source_cap - len(helper_body))
            for body in (helper_body, at_cap, at_cap + b"\n"):
                path = tools / "macos_android_helper_package.py"
                path.write_bytes(body); path.chmod(0o644)
                port = module.Operation(SimpleNamespace(), root, root, "package-install",
                    {"GITHUB_SHA": "a" * 40, "GITHUB_WORKFLOW_SHA": "a" * 40, "GITHUB_WORKFLOW_REF": "inert-source",
                     "GITHUB_RUN_ID": "123", "GITHUB_RUN_ATTEMPT": "1", "MRK_MACOS_PACKAGE_ROLE": "ordinary-image"}, TOOL)
                try:
                    if len(body) > source_cap:
                        with self.assertRaisesRegex(module.Refused, "^file-original-shape$"):
                            port.source_original("desktop/tools/macos_android_helper_package.py", "SOURCE-test", module.HELPER_SOURCE_BYTES)
                    else:
                        entry = port.source_original("desktop/tools/macos_android_helper_package.py", "SOURCE-test", module.HELPER_SOURCE_BYTES)
                        self.assertEqual(port.read(entry), body)
                finally:
                    for entry in reversed(port.entries): port.close(entry)
                self.assertFalse(port.errors)
                self.assertTrue(all(entry["closed"] and entry["fd"] is None for entry in port.entries))

        # Actual package-image/original/custody/close methods; only native tool
        # returns and Darwin metadata syscalls are synthetic DATA on Linux.
        # These cannot qualify a native image, signing identity or installation.
        for case in ("zero", "finder", "unknown", "extra", "malformed", "bad-value", "query-error",
                     "list-changed", "remove-error", "post-attribute", "same-size-bytes", "named-replaced",
                     "mode-changed", "deadline", "short-read", "extra-byte", "close-error", "primary-and-close"):
            with self.subTest(createdImage=case), tempfile.TemporaryDirectory(prefix="mrk-created-image-") as temporary:
                root = Path(temporary); root.chmod(0o700)
                port = module.Operation(SimpleNamespace(), root, root, "package-install",
                    {"GITHUB_SHA": "a" * 40, "GITHUB_WORKFLOW_SHA": "a" * 40,
                     "GITHUB_WORKFLOW_REF": "inert-created-image", "GITHUB_RUN_ID": "123",
                     "GITHUB_RUN_ATTEMPT": "1", "MRK_MACOS_PACKAGE_ROLE": "ordinary-image"}, TOOL)
                port.work_entry = port.register(os.open(root, module.READ_FLAGS | os.O_DIRECTORY), "work", "directory")
                port.work_entry["identity"] = module.directory_identity(os.fstat(port.work_entry["fd"]))
                port.package_started = port.package_observed = module.time.monotonic_ns()
                port.package_endpoint = port.package_started + 10_000_000_000
                (root / "distribution").mkdir(mode=0o700)
                port.distribution_entry = port.directory(port.work_entry, "distribution", "image-parent")
                path = root / "distribution/MobileReleaseKit.dmg"
                payload, signed, removed, original_fds = b"INERT_UDIF_IMAGE_DATA", [], [], []
                metadata = [b"" if case == "zero" else b"com.apple.FinderInfo\0"]
                if case in ("unknown", "primary-and-close"): metadata[0] = b"com.apple.Quarantine\0"
                if case == "extra": metadata[0] += b"com.apple.ResourceFork\0"
                if case == "malformed": metadata[0] = b"com.apple.FinderInfo"
                class MetadataData:
                    def names(self, fd):
                        original_fds.append(fd)
                        if case == "query-error": raise module.Refused("created-image-query-data")
                        if case == "deadline": port.package_endpoint = port.package_started
                        return metadata[0]
                    def finder_info(self, fd):
                        if case == "list-changed": metadata[0] = b"com.apple.ResourceFork\0"
                        return b"F" * (31 if case == "bad-value" else 32)
                    def remove_finder_info(self, fd):
                        removed.append(fd)
                        if case == "remove-error": raise module.Refused("created-image-remove-data")
                        metadata[0] = b"unexpected\0" if case == "post-attribute" else b""
                        if case == "same-size-bytes":
                            before = os.fstat(fd)
                            writing = os.open(path, os.O_WRONLY | os.O_NOFOLLOW | os.O_CLOEXEC)
                            try:
                                self_test.assertEqual(os.pwrite(writing, b"Y" * len(payload), 0), len(payload))
                                os.utime(writing, ns=(before.st_atime_ns, before.st_mtime_ns))
                            finally: os.close(writing)
                        if case == "named-replaced":
                            path.rename(path.with_suffix(".retained")); path.write_bytes(payload)
                        if case == "mode-changed": os.fchmod(fd, 0o600)
                self_test = self
                metadata_api = MetadataData()
                actual_policy, actual_close, actual_pread = TOOL.no_xattrs, port.close, os.pread
                def policy(fd):
                    actual_policy(fd)
                    module.need(metadata[0] == b"", "created-image-post-policy-data")
                def native_return(role, argv, **kwargs):
                    if role == "distribution-create":
                        self.assertFalse(path.exists()); path.write_bytes(payload); path.chmod(0o644)
                    if role == "distribution-sign":
                        signed.append(role)
                        normalization = [entry for entry in port.entries if entry["role"] == "distribution-created-image"]
                        self.assertEqual(len(normalization), 1)
                        self.assertTrue(normalization[0]["closed"] and normalization[0]["fd"] is None)
                        self.assertEqual(path.read_bytes(), payload); self.assertEqual(metadata[0], b"")
                    port.calls.append({"role": role, "returned": True, "capturesSettled": True})
                    return CompletedProcess(argv, 0, b"", b"")
                def consume(entry):
                    if entry["role"] == "distribution-created-image" and case in ("close-error", "primary-and-close"):
                        real = os.close
                        def close_error(fd):
                            real(fd)
                            raise OSError("inert closed-original uncertainty")
                        with mock.patch.object(module.os, "close", new=close_error): actual_close(entry)
                    else: actual_close(entry)
                def read(fd, size, offset):
                    if original_fds and fd == original_fds[0]:
                        if case == "short-read" and offset == 0: return b""
                        if case == "extra-byte" and offset == len(payload): return b"!"
                    return actual_pread(fd, size, offset)
                port.signing = ("TEST000001", "a" * 40)
                try:
                    with (mock.patch.object(module, "_CreatedDmgXattrs", return_value=metadata_api),
                          mock.patch.object(TOOL, "no_xattrs", new=policy),
                          mock.patch.object(port, "package_call", new=native_return),
                          mock.patch.object(port, "credential_scope", return_value=contextlib.nullcontext()),
                          mock.patch.object(port, "close", new=consume),
                          mock.patch.object(module.os, "pread", new=read)):
                        if case in ("zero", "finder"):
                            value, output = port.package_image({"name": "inert-input"}, "distribution")
                            self.assertEqual(output, path); self.assertEqual(value["sha256"], module.digest(payload))
                        else:
                            expected_reason = {"same-size-bytes": "created-image-normalization-bytes",
                                "primary-and-close": "created-image-only-finder-info",
                                "close-error": "created-image-close-unknown"}.get(case)
                            with self.assertRaises(module.Refused) as raised:
                                port.package_image({"name": "inert-input"}, "distribution")
                            if expected_reason: self.assertEqual(str(raised.exception), expected_reason)
                    self.assertEqual(bool(signed), case in ("zero", "finder"))
                    self.assertLessEqual(len(removed), 1)
                    self.assertTrue(all(fd == original_fds[0] for fd in original_fds))
                    if case in ("unknown", "extra", "malformed", "bad-value", "query-error", "list-changed",
                                "deadline", "short-read", "extra-byte", "primary-and-close"):
                        self.assertEqual(removed, [])
                    normalized = [entry for entry in port.entries if entry["role"] == "distribution-created-image"]
                    self.assertEqual(len(normalized), 1)
                    self.assertIsNone(normalized[0]["fd"])
                    self.assertEqual(normalized[0]["closed"], case not in ("close-error", "primary-and-close"))
                    self.assertEqual(len(port.errors), int(case in ("close-error", "primary-and-close")))
                    self.assertNotIn(normalized[0], [entry for entry, _ in port.package_outputs])
                finally:
                    for entry in reversed(port.entries): port.close(entry)
                self.assertTrue(all(entry["fd"] is None for entry in port.entries))

        # Actual ordinary-file mutation seam, never a native stapler receipt.
        # Every original FD is registered and consumed once by this test owner.
        faults = (None, "mode", "links", "unlinked", "empty", "growth", "binding", "query", "attrs", "foreign", "unknown-args", "extra-args", "foreign-string", "unexpected", "stream")
        synthetic_receipt = {"GITHUB_SHA": "a" * 40, "GITHUB_WORKFLOW_SHA": "a" * 40,
                             "GITHUB_WORKFLOW_REF": "SYNTHETIC SOURCE DATA", "GITHUB_RUN_ID": "123", "GITHUB_RUN_ATTEMPT": "1"}
        expected = {"mode": "held-mode", "links": "held-links-other", "unlinked": "held-links-unlinked",
                    "empty": "size", "growth": "growth", "binding": "binding", "query": "xattr-query",
                    "attrs": "xattrs-present", "foreign": "xattr-query", "unknown-args": "xattr-query",
                    "extra-args": "xattr-query", "foreign-string": "xattr-query", "unexpected": "xattr-query", "stream": "stream"}
        class ForeignXattrs(TOOL.Refused):
            pass
        class ForeignLiteral(str):
            pass
        for fault in faults:
            with self.subTest(stapleGate=fault), tempfile.TemporaryDirectory() as directory:
                root = Path(directory); root.chmod(0o700)
                path = root / "image.dmg"; path.write_bytes(b"before"); path.chmod(0o600)
                selected = module.Operation(SimpleNamespace(), root, root, "finalize-image", synthetic_receipt, TOOL)
                parent = selected.register(os.open(root, os.O_RDONLY | os.O_DIRECTORY), "test-parent", "directory")
                parent["identity"] = module.directory_identity(os.fstat(parent["fd"]))
                selected.work_entry = parent
                entry = selected.register(os.open(path, os.O_RDWR | os.O_NOFOLLOW), "test-image", "file", parent["fd"], path.name)
                entry.update(parent_entry=parent, identity=module.signature(os.fstat(entry["fd"])))
                selected.final_image_output = entry; selected.final_image_sha = module.digest(b"before")
                selected.notary_started = selected.notary_observed = module.time.monotonic_ns()
                selected.notary_mutation_pending = True
                original_identity = entry["identity"]; primary = RuntimeError("inert stream failure")
                xattr_error = {"foreign": ForeignXattrs("file-extended-attributes"),
                    "unknown-args": TOOL.Refused("inert unknown argument"),
                    "extra-args": TOOL.Refused("file-extended-attributes", "inert extra argument"),
                    "foreign-string": TOOL.Refused(ForeignLiteral("file-extended-attributes")),
                    "unexpected": primary}.get(fault)
                try:
                    path.write_bytes(b"after-original")
                    if fault == "mode": path.chmod(0o644)
                    elif fault == "links": os.link(path, root / "second")
                    elif fault == "unlinked":
                        other = root / "replacement"; other.write_bytes(b"after-original"); other.chmod(0o600); other.replace(path)
                    elif fault == "empty": path.write_bytes(b"")
                    elif fault == "binding":
                        path.rename(root / "retained"); path.write_bytes(b"after-original"); path.chmod(0o600)
                    with contextlib.ExitStack() as ports:
                        if fault == "growth":
                            # Observe an excessive growth through the fixed stat
                            # DATA port, not a file exceeding this owner's 1MiB
                            # write cap. All other held fields are genuine.
                            real_fstat = module.os.fstat
                            def excessive_growth(fd):
                                info = real_fstat(fd)
                                if fd != entry["fd"]: return info
                                fields = {name: getattr(info, name) for name in ("st_dev", "st_ino", "st_mode", "st_nlink", "st_uid", "st_gid", "st_size", "st_mtime_ns", "st_ctime_ns")}
                                fields["st_size"] = 1024 * 1024 + original_identity[6] + 1
                                return SimpleNamespace(**fields)
                            ports.enter_context(mock.patch.object(module.os, "fstat", side_effect=excessive_growth))
                        elif fault in ("query", "attrs"):
                            ports.enter_context(mock.patch.object(TOOL.sys, "platform", "darwin"))
                            ports.enter_context(mock.patch.object(TOOL, "_DARWIN_XATTRS", return_value=(-1 if fault == "query" else 1)))
                        elif xattr_error is not None:
                            ports.enter_context(mock.patch.object(TOOL, "no_xattrs", side_effect=xattr_error))
                        elif fault == "stream": ports.enter_context(mock.patch.object(selected, "notary_stream", side_effect=primary))
                        if fault is None:
                            selected.final_image_mutated(original_identity)
                            self.assertFalse(selected.notary_mutation_pending)
                            self.assertEqual(selected.final_image_sha, module.digest(b"after-original"))
                            self.assertEqual(selected.notary_stream(entry), selected.final_image_sha)
                        else:
                            with self.assertRaises(BaseException) as caught: selected.final_image_mutated(original_identity)
                            self.assertEqual(selected.stage, "final-image-staple-" + expected[fault])
                            self.assertTrue(selected.notary_mutation_pending)
                            if fault == "stream": self.assertIs(caught.exception, primary)
                            elif fault == "query": self.assertEqual(BaseException.args.__get__(caught.exception), ("file-extended-attributes-query",))
                            elif fault == "attrs": self.assertEqual(BaseException.args.__get__(caught.exception), ("file-extended-attributes",))
                            elif xattr_error is not None: self.assertIs(caught.exception, xattr_error)
                            else: self.assertEqual(BaseException.args.__get__(caught.exception), ("final-image-stapled-original",))
                    self.assertEqual(selected.calls, [])  # No native or later validate entry.
                    self.assertFalse(selected.notary_complete)
                finally:
                    for original in reversed(selected.entries): selected.close(original)
                    self.assertTrue(all(row["fd"] is None and row["closed"] for row in selected.entries))
                    self.assertEqual(selected.errors, [])

        # Fixed call port exercises the actual returned-original clock/POST
        # catch. It is synthetic DATA, never native command/finality evidence.
        for fault in (None, "clock", "post"):
            with self.subTest(stapleCall=fault):
                selected = module.Operation(SimpleNamespace(), Path("/inert"), Path("/inert/work"), "finalize-image", synthetic_receipt, TOOL)
                selected.calls = [{"returned": True, "capturesSettled": True} for _ in module.FINAL_IMAGE_ROLES[:5]]
                selected.final_image_output = {"identity": tuple(range(9))}
                primary = RuntimeError("inert original boundary failure"); counts = {"clock": 0, "post": 0}
                def clock():
                    counts["clock"] += 1
                    if fault == "clock" and counts["clock"] == 2: raise primary
                    return 10_000_000_000, 1740_000_000_000
                def post():
                    counts["post"] += 1
                    if fault == "post" and counts["post"] >= 2: raise primary
                def mutated(before, **same_call):
                    self.assertEqual(before, tuple(range(9)))
                    self.assertEqual(set(same_call), {"before_entry", "before_sha"})
                    self.assertIs(same_call["before_entry"], selected.final_image_output)
                    self.assertEqual(same_call["before_sha"], selected.final_image_sha)
                    selected.notary_mutation_pending = False
                result = object()
                with (mock.patch.object(selected, "notary_clock", side_effect=clock),
                      mock.patch.object(selected, "notary_post", side_effect=post),
                      mock.patch.object(selected, "native_environment", return_value={}),
                      mock.patch.object(selected, "call", return_value=result),
                      mock.patch.object(selected, "final_image_mutated", side_effect=mutated)):
                    if fault is None:
                        self.assertIs(selected.final_image_call("final-image-staple", []), result)
                        self.assertEqual(selected.stage, "final-image-staple")
                        self.assertFalse(selected.notary_mutation_pending or selected.notary_unknown)
                    else:
                        with self.assertRaises(RuntimeError) as caught: selected.final_image_call("final-image-staple", [])
                        self.assertIs(caught.exception, primary)
                        self.assertEqual(selected.stage, "final-image-staple-" + fault)
                        self.assertEqual(selected.notary_mutation_pending, fault == "clock")
                        self.assertEqual(selected.notary_unknown, fault == "post")
                        self.assertEqual(len(selected.errors), 1 if fault == "post" else 0)
                    self.assertFalse(selected.notary_complete)
                    self.assertEqual(len(selected.calls), 5)  # Inert call port did not fabricate a receipt.

        # Same-call unlink observer: ordinary tiny originals, no native tools.
        # A named stat is not output custody; the original failure always remains.
        for fault in (None, "mode", "missing", "extra", "pre-bytes", "pre-metadata", "short-read", "extra-byte",
                      "xattrs", "deadline", "name-race", "parent-race", "close-unknown", "foreign-primary"):
            with self.subTest(unlinkObservation=fault), tempfile.TemporaryDirectory(prefix="mrk-unlink-observe-") as directory:
                root = Path(directory); root.chmod(0o700)
                path = root / "MobileReleaseKit.dmg"; payload = b"retained-PRE-data"; path.write_bytes(payload); path.chmod(0o600)
                selected = module.Operation(SimpleNamespace(), root, root, "finalize-image", synthetic_receipt, TOOL)
                parent = selected.register(os.open(root, module.READ_FLAGS | os.O_DIRECTORY), "unlink-parent", "directory")
                parent["identity"] = module.directory_identity(os.fstat(parent["fd"]))
                selected.work_entry = selected.final_image_output_root = parent
                entry = selected.register(os.open(path, os.O_RDWR | os.O_NOFOLLOW), "final-image-copy", "file", parent["fd"], path.name)
                entry.update(parent_entry=parent, identity=module.signature(os.fstat(entry["fd"])))
                selected.final_image_output = entry; selected.final_image_sha = module.digest(payload)
                selected.notary_started = selected.notary_observed = module.time.monotonic_ns()
                selected.calls = [{"role": role, "returned": True, "capturesSettled": True, "returncode": 0}
                                  for role in module.FINAL_IMAGE_ROLES[:5]]
                original_identity, original_sha = entry["identity"], selected.final_image_sha
                actual_pread, actual_mutated, actual_close = module.os.pread, selected.final_image_mutated, selected.close
                primaries, reads, closes = [], [], []
                def native_data(role, argv, environment, **kwargs):
                    self.assertEqual(role, "final-image-staple")
                    self.assertEqual((entry["identity"], selected.final_image_sha), (original_identity, original_sha))
                    other = root / "replacement"; other.write_bytes(b"returned-name-data"); other.chmod(0o600); other.replace(path)
                    if fault == "mode": path.chmod(0o644)
                    if fault == "missing": path.unlink()
                    if fault == "extra": (root / "extra").write_bytes(b"x")
                    if fault in ("pre-bytes", "pre-metadata"):
                        if fault == "pre-bytes": os.pwrite(entry["fd"], b"X" * len(payload), 0)
                        else: os.fchmod(entry["fd"], 0o644)
                        os.utime(entry["fd"], ns=(os.fstat(entry["fd"]).st_atime_ns, original_identity[7]))
                    selected.calls.append({"role": role, "returned": True, "capturesSettled": True, "returncode": 0})
                    return CompletedProcess(argv, 0, b"", b"")
                def mutate(before, **same_call):
                    self.assertEqual(set(same_call), {"before_entry", "before_sha"})
                    self.assertIs(same_call["before_entry"], entry)
                    self.assertEqual(same_call["before_sha"], original_sha)
                    # This legacy failure-only observer fixture deliberately
                    # omits the captured-entry keyword on the real call. It
                    # does not opt into functional returned-output adoption.
                    if fault == "foreign-primary":
                        error = ForeignXattrs("final-image-stapled-original")
                        selected.stage = "final-image-staple-held-links-unlinked"; primaries.append(error); raise error
                    try: return actual_mutated(before)
                    except BaseException as error: primaries.append(error); raise
                def read(number, size, offset):
                    if number == entry["fd"]:
                        reads.append(number)
                        if fault == "short-read" and offset == 0: return b""
                        if fault == "extra-byte" and offset == len(payload): return b"!"
                        result = actual_pread(number, size, offset)
                        if offset == 0:
                            if fault == "deadline": selected.notary_started -= 1740_000_000_000
                            if fault == "name-race":
                                replacement = root / "replacement"; replacement.write_bytes(b"other-name-data"); replacement.chmod(0o600); replacement.replace(path)
                            if fault == "parent-race": root.chmod(0o750)
                        return result
                    return actual_pread(number, size, offset)
                try:
                    with contextlib.ExitStack() as ports:
                        ports.enter_context(mock.patch.object(selected, "notary_post", return_value=None))
                        ports.enter_context(mock.patch.object(selected, "native_environment", return_value={}))
                        ports.enter_context(mock.patch.object(selected, "call", side_effect=native_data))
                        ports.enter_context(mock.patch.object(selected, "final_image_mutated", side_effect=mutate))
                        ports.enter_context(mock.patch.object(module.os, "pread", side_effect=read))
                        if fault == "xattrs": ports.enter_context(mock.patch.object(TOOL, "no_xattrs", side_effect=TOOL.Refused("inert-xattr-data")))
                        with self.assertRaises(BaseException) as caught: selected.final_image_call("final-image-staple", [])
                        self.assertIs(caught.exception, primaries[0])
                    observation = selected.receipt.get("finalImageUnlinkObservation")
                    if fault in ("pre-metadata", "foreign-primary"):
                        self.assertIsNone(observation)
                    else:
                        self.assertIsInstance(observation, dict)
                        self.assertEqual(observation["state"], "observed" if fault in (None, "mode", "close-unknown") else "refused")
                        self.assertFalse(observation["outputAdopted"] or observation["transitionComplete"])
                        if fault == "mode": self.assertFalse(observation["namedModeExpected"])
                        if fault is None: self.assertTrue(all(observation[name] for name in module.FINAL_IMAGE_UNLINK_FLAGS))
                    if fault not in ("pre-metadata", "foreign-primary"):
                        self.assertEqual(selected.stage, "final-image-staple-held-links-unlinked")
                    self.assertTrue(selected.notary_mutation_pending)
                    self.assertFalse(selected.notary_unknown or selected.notary_complete or selected.final_image_complete)
                    self.assertEqual((entry["identity"], selected.final_image_sha), (original_identity, original_sha))
                    self.assertIsNone(selected.final_package_preimage)
                    self.assertEqual(len(selected.entries), 2)  # No diagnostic descriptor/adoption.
                    self.assertEqual(len(selected.calls), 6)
                    self.assertEqual(selected.errors, [])
                finally:
                    root.chmod(0o700)
                    for original in reversed(selected.entries):
                        number = original["fd"]; closes.append(number)
                        if fault == "close-unknown" and original is entry:
                            real_close = os.close
                            def uncertain(number): real_close(number); raise OSError("inert consumed-close uncertainty")
                            with mock.patch.object(module.os, "close", side_effect=uncertain): actual_close(original)
                        else: actual_close(original)
                    for original in selected.entries: selected.close(original)
                    self.assertEqual(len(closes), len(set(closes)))
                    self.assertTrue(all(row["fd"] is None for row in selected.entries))
                    self.assertEqual(len(selected.errors), int(fault == "close-unknown"))
                    self.assertFalse(selected.final_image_known())
                    if fault != "missing": self.assertTrue(path.exists())

