                    self.assertEqual(TOOL.tree(base / "carrier"), {TOOL.XCODE_SETUP_CARRIER+"/Contents/Info.plist": (setup_source["CarrierInfo.plist"], 0o444)})
                    (base / "packager/PrepareXcode-original.pkg").write_bytes(original)
