                    self.assertEqual(record["finalPackage"]["signedSha256"], module.digest(fixture.signed))
                    self.assertEqual(record["finalPackage"]["packageSha256"], returned)
                    self.assertEqual(record["finalPackage"]["ticketRowCount"], 1)
