def maintenance_documents(actions=("fresh-install",), *, target="aarch64-apple-darwin", launcher=False, recovery=False):
    """Synthetic closed records; no real signature, installer or native event."""
    prefix = "macos26-arm64-" if target == "aarch64-apple-darwin" else "macos26-x86_64-"
    profile = "fixed-macos26-arm64-maintenance-v2" if target == "aarch64-apple-darwin" else "fixed-macos26-x86_64-maintenance-v2"
    policy = {"schemaVersion": 1, "kind": "mrk-macos-developer-id-code-policy-v1", "teamIdentifier": "TEAM000001",
              "leafCertificateSha1": "1" * 40, "leafCertificateSha256": "2" * 64, "hardenedRuntime": True, "entitlements": "empty"}
    policy_hash = TOOL.digest(json.dumps(policy, separators=(",", ":")).encode("ascii"))
    def release(number):
        return {"profile": profile, "packageIdentifier": "dev.mobile-release-kit.desktop.installed",
                "bundleIdentifier": "dev.mobile-release-kit.desktop", "packageVersion": f"0.{number}.0",
                "release": prefix + f"ordinary-data-{number}", "sourceCommit": "a" * 40, "protocolSha256": TOOL.CURRENT_PROTOCOL,
                "runtimeManifestSha256": "c" * 64, "inventorySha256": "b" * 64, "signingPolicySha256": policy_hash,
                "packageSha256": "d" * 64 if number == 3 else "e" * 64}
    producer = {"schemaVersion": 2, "kind": "mrk-macos-install-producer-v2", "domain": "MobileReleaseKit-package-producer-v2", "target": target,
                "releaseSet": {"schemaVersion": 2, "current": release(3), "acceptedPredecessors": [release(2)]},
                "signingPolicies": [{"sha256": policy_hash, "policy": policy}]}
    def identity(inode, mode):
        return {"device": 1, "inode": inode, "mode": stat.S_IFDIR | mode, "uid": 0, "gid": 0, "flags": 0}
    records, evidence, previous = {}, [], None
    for index, action in enumerate(actions, 1):
        invocation, request_id = f"{index:032x}", f"{100+index:032x}"
        selected = release(2 if "update" in actions[index:] else 3)
        intent = {"schemaVersion": 2, "kind": "mrk-macos-maintenance-intent-v2", "target": target,
                  "invocation": invocation, "requestId": request_id, "action": action,
                  "previous": None if previous is None else previous["current"]["release"], "next": selected,
                  "previousState": None if previous is None else {"invocation": previous["invocation"],
                      "sha256": TOOL.digest(records[previous["invocation"]][1])}}
        generation = {"release": selected, "instance": invocation if recovery else f"{1000+index:032x}", "releaseDirectory": identity(200+index, 0o755),
                      "app": {"location": "canonical", "identity": identity(300+index, 0o555)}}
        retained = [] if previous is None else copy.deepcopy(previous["retained"])
        if action == "same-package-noop":
            generation = copy.deepcopy(previous["current"])
        elif action == "restore-fixed-app":
            generation = {**copy.deepcopy(previous["current"]), "app": generation["app"]}
        elif action == "update":
            retained.append({**copy.deepcopy(previous["current"]), "app": {"location": "retained", "invocation": invocation,
                             "identity": copy.deepcopy(previous["current"]["app"]["identity"])}})
        state = {"schemaVersion": 2, "kind": "mrk-macos-maintenance-state-v2", "target": target, "invocation": invocation,
                 "requestId": request_id, "capsuleInvocation": invocation, "intendedAction": action, "phase": "mutation-recorded",
                 "current": generation, "retained": retained, "previousEvidence": list(evidence), "residue": None}
        if recovery and action == "same-package-noop":
            reference = {"stageInvocation": generation["instance"], "tornInvocation": f"{9000+index:032x}",
                         "receiptSha256": "f" * 64}
            intent["recovery"], state["recovery"] = copy.deepcopy(reference), copy.deepcopy(reference)
        raw_intent, raw_state = TOOL.canonical(intent) + b"\n", TOOL.canonical(state) + b"\n"
        count = 0 if action == "same-package-noop" else 24577
        writer = {"returned": True, "exitCode": 0, "originalJoined": True, "resultEof": True, "originalClosesKnown": True,
                  "withinOriginalDeadline": True, "payloadWriteCount": count, "payloadWriteBytes": count}
        capsule = {"schemaVersion": 2, "kind": "mrk-macos-maintenance-capsule-v2", "target": target, "invocation": invocation,
                   "requestId": request_id, "intendedAction": action, "previous": intent["previous"], "next": selected,
                   "actualCurrent": selected, "intentSha256": TOOL.digest(raw_intent), "stateSha256": TOOL.digest(raw_state),
                   "outcome": {"fresh-install": "applied", "update": "applied", "same-package-noop": "same-package", "restore-fixed-app": "restored-app"}[action],
                   "writer": writer}
        if launcher:
            capsule["launcher"] = maintenance_launcher_fixture("restored" if action == "same-package-noop" else "published")
        raw_capsule = TOOL.canonical(capsule) + b"\n"
        records[invocation] = (raw_intent, raw_state, raw_capsule)
        hashes = {"intentSha256": TOOL.digest(raw_intent), "stateSha256": TOOL.digest(raw_state), "capsuleSha256": TOOL.digest(raw_capsule)}
        evidence.append({"invocation": invocation, **hashes})
        evidence.sort(key=lambda row: row["invocation"])
        previous = state
    result = {"schemaVersion": 2, "kind": "maintenance-parent-pending-finalization", "invocation": invocation, "requestId": request_id,
              "resultName": f"MobileReleaseKit-InstallerResult-v2-{request_id}.json",
              "resultFinality": "pending-own-write-readback-close-and-outer-return", "action": action,
              "writerState": {"fresh-install": "installed", "update": "installed", "same-package-noop": "same-package", "restore-fixed-app": "restored-app"}[action],
              "writerExit": 0, **hashes, "payloadWriteCount": count, "payloadWriteBytes": count, "originalWriterJoined": True,
              "parentFinality": "pending-original-closes-and-outer-return", "retainedGate": "parent-command-reference-until-kernel-exit",
              "historicalOuterExit": "unverified",
              "registrationReservation": reservation_result_data(created=actions[-1] == "fresh-install")}
    return producer, records, result


def maintenance_restore_fixture(producer, records, result, root_identity, *, nested=False, repeated=False, cross_alias=False):
    """Native-shaped synthetic receipt forest; no Rust execution or private-body evidence."""
    records = dict(records)
    invocation = sorted(records)[1]
    intent, state, capsule = [TOOL.decode(body) for body in records[invocation]]
    previous = intent["previousState"]["invocation"]
    files, facts, names, groups = {}, {}, set(), []
    def identity(inode):
        return dict(device=root_identity["device"], inode=inode, birthSeconds=1, birthNanoseconds=0)
    root = identity(root_identity["inode"]); old_state = identity(8000)
    def body(value): return json.dumps(value, separators=(",", ":"), ensure_ascii=False).encode() + b"\n"
    def native_intent(value):
        keys = ("schemaVersion", "kind", "target", "invocation", "requestId", "action", "previous", "next", "previousState")
        release = ("profile", "packageIdentifier", "bundleIdentifier", "packageVersion", "release", "sourceCommit",
                   "protocolSha256", "runtimeManifestSha256", "inventorySha256", "signingPolicySha256", "packageSha256")
        ordered = {key: value[key] for key in keys}
        for key in ('previous', 'next'): ordered[key] = {k: value[key][k] for k in release}
        ordered['previousState'] = {k: value['previousState'][k] for k in ('invocation', 'sha256')}
        if 'restoreRecovery' in value: ordered['restoreRecovery'] = {k: value['restoreRecovery'][k] for k in ('tornInvocation','receiptInvocation','receiptSha256')}
        return body(ordered)
    def file(name, raw, original=None, mode=0o444):
        inode = original['inode'] if original else 20000 + len(facts)
        files[name] = raw
        facts[name] = log_info(len(raw), st_dev=root['device'], st_ino=inode, st_mode=stat.S_IFREG|mode,
                               st_uid=0, st_gid=0, st_nlink=1, st_flags=0)
    base = copy.deepcopy(intent); base.update(invocation=f'{100:032x}',requestId=f'{1100:032x}')
    base_raw = native_intent(base); base_identity = identity(10000)
    final_raw = None
    for group_index in range(2 if nested else 1):
        torn = base['invocation']; stage = identity(9000+(0 if cross_alias else group_index))
        stage_name = '.restore-recovery-'+torn+'.stage'
        facts[stage_name] = log_info(st_dev=root['device'],st_ino=stage['inode'],st_mode=stat.S_IFDIR|0o700,
                                     st_uid=0,st_gid=0,st_nlink=3,st_flags=0)
        names.add(stage_name)
        base_name = '.restore-recovery-'+torn+'-'+torn+'.intent.json'
        file(base_name,base_raw,base_identity);names.add(base_name)
        expected = [(base,base_raw,base_identity)]
        holder_id = f'{200:032x}' if nested and group_index == 0 else invocation
        own_ids = ([f'{110+group_index*100:032x}'] if repeated else []) + [holder_id]
        for own_index, own_id in enumerate(own_ids):
            request = intent['requestId'] if own_id == invocation else f'{int(own_id,16)+1000:032x}'
            own_identity = identity(10000+int(own_id,16))
            receipt = dict(schemaVersion=1,kind='mrk-restore-app-prepublication-preservation-v1',target=producer['target'],
                tornInvocation=torn,previousStateSha256=TOOL.digest(records[previous][1]),previousCapsuleSha256=TOOL.digest(records[previous][2]),
                root=root,stage=stage,oldState=old_state,stageSha256='0'*64,
                ownAttempt=dict(invocation=own_id,requestId=request,identity=own_identity),
                attempts=sorted([dict(invocation=i['invocation'],requestId=i['requestId'],intentSha256=TOOL.digest(raw),identity=ident)
                                 for i,raw,ident in expected],key=lambda row:row['invocation']))
            receipt_raw = body(receipt); receipt_name='.restore-recovery-'+own_id+'.json'
            file(receipt_name,receipt_raw);names.add(receipt_name)
            retry=copy.deepcopy(base);retry.update(invocation=own_id,requestId=request,
                restoreRecovery=dict(tornInvocation=torn,receiptInvocation=own_id,receiptSha256=TOOL.digest(receipt_raw)))
            retry_raw=native_intent(retry);expected.append((retry,retry_raw,own_identity))
            if own_id != holder_id:
                name='.restore-recovery-'+torn+'-'+own_id+'.intent.json'
                file(name,retry_raw[:11],own_identity,mode=0o600);names.add(name)
        groups.append((receipt,receipt_raw,base,base_raw))
        base,base_raw,base_identity=expected[-1]
        final_raw=base_raw
    state['restoreRecovery']=copy.deepcopy(base['restoreRecovery'])
    state_raw=TOOL.canonical(state)+b'\n';capsule.update(intentSha256=TOOL.digest(final_raw),stateSha256=TOOL.digest(state_raw))
    records[invocation]=(final_raw,state_raw,TOOL.canonical(capsule)+b'\n')
    # Rebind later ordinary successful history without creating new recovery references.
    evidence=[]
    for key in sorted(records):
        old_intent,old_state_doc,old_capsule=[TOOL.decode(raw) for raw in records[key]]
        if key > invocation:
            old_intent['previousState']['sha256']=TOOL.digest(records[old_intent['previousState']['invocation']][1])
            old_state_doc['previousEvidence']=copy.deepcopy(evidence)
            ir,sr=TOOL.canonical(old_intent)+b'\n',TOOL.canonical(old_state_doc)+b'\n'
            old_capsule.update(intentSha256=TOOL.digest(ir),stateSha256=TOOL.digest(sr))
            records[key]=(ir,sr,TOOL.canonical(old_capsule)+b'\n')
        hashes=dict(zip(('intentSha256','stateSha256','capsuleSha256'),map(TOOL.digest,records[key])))
        evidence.append(dict(invocation=key,**hashes))
    result={**result,**hashes}
    file('.maintenance-'+previous+'.state.json',records[previous][1],old_state)
    file('.maintenance-'+invocation+'.intent.json',final_raw,base_identity)
    return SimpleNamespace(records=records,result=result,files=files,facts=facts,names=names,groups=groups,
                           private={name for name,info in facts.items() if stat.S_IMODE(info.st_mode) in (0o600,0o700)})


