    def actual_workflow_binding(self, target, *, installed, candidate=False, update=False):
        """Run only the actual passive producer nodes with synthetic public observations."""
        workflow = (Path(__file__).absolute().parents[2] / ".github/workflows/desktop-macos-installed.yml").read_text()
        marker = '"$MRK_PYTHON" -I -S -B - "$root/source-admission.json" <<\'PY\'\n'
        self.assertEqual(workflow.count(marker), 1)
        block = workflow.split(marker, 1)[1].split("          PY\n", 1)[0]
        self.assertTrue(all(not line or line.startswith("          ") for line in block.splitlines()))
        parsed = ast.parse("\n".join(line[10:] for line in block.splitlines()))
        assignments = {node.targets[0].id: node for node in parsed.body
                       if isinstance(node, ast.Assign) and len(node.targets) == 1
                       and isinstance(node.targets[0], ast.Name)}
        refs = {"refs/heads/verify/desktop-macos-installed", "refs/heads/verify/desktop-macos-preview"}
        if candidate:
            refs.add("refs/heads/verify/desktop-macos-candidate")
        if update:
            refs.add("refs/heads/verify/desktop-macos-positive-update")
        selected = [node for node in parsed.body if isinstance(node, ast.If)
                    and isinstance(node.test, ast.Compare) and len(node.test.ops) == 1
                    and isinstance(node.test.ops[0], ast.Eq) and len(node.test.comparators) == 1
                    and isinstance(node.test.comparators[0], ast.Constant) and node.test.comparators[0].value in refs]
        self.assertEqual(len(selected), len(refs))
        self.assertTrue(all(ast.unparse(node.test.left) == "os.environ['GITHUB_REF']" for node in selected))
        program = ast.Module(body=[assignments["value"], *selected], type_ignores=[])
        # Admission producer calls are only local dict updates: never execute tools/Git/native owners.
        for node in ast.walk(program):
            if isinstance(node, ast.Call):
                self.assertTrue(isinstance(node.func, ast.Attribute) and isinstance(node.func.value, ast.Name)
                                and node.func.value.id == "value" and node.func.attr == "update")
        keys = {node.slice.value for node in ast.walk(program) if isinstance(node, ast.Subscript)
                and isinstance(node.value, ast.Attribute) and isinstance(node.value.value, ast.Name)
                and node.value.value.id == "os" and node.value.attr == "environ"
                and isinstance(node.slice, ast.Constant) and type(node.slice.value) is str}
        self.assertLessEqual(len(keys), 64)
        self.assertFalse(any(any(sensitive in key for sensitive in ("PASSWORD", "BASE64", "TOKEN")) for key in keys))
        env = {key: "c" * 64 for key in keys}
        env.update(GITHUB_REF="refs/heads/verify/desktop-macos-positive-update" if update else "refs/heads/verify/desktop-macos-candidate" if candidate else
                   "refs/heads/verify/desktop-macos-installed" if installed else "refs/heads/verify/desktop-macos-preview",
                   GITHUB_SHA="a" * 40, GITHUB_WORKFLOW_SHA="a" * 40, GITHUB_RUN_ID="123", GITHUB_RUN_ATTEMPT="1",
                   MRK_MACOS_PACKAGE_ROLE="ordinary-image", MRK_MACOS_TARGET=target, DEVELOPER_DIR="/synthetic-sdk")
        namespace = {"os": os, "build_target": target, "tools": {}, "source_tree": "b" * 40,
                     "work_info": SimpleNamespace(st_dev=1, st_ino=2, st_uid=os.getuid()),
                     "supplier_routes": ast.literal_eval(assignments["supplier_routes"].value)}
        with mock.patch.dict(os.environ, env, clear=True):
            exec(compile(program, "actual-passive-workflow-binding", "exec"), namespace)
        binding = namespace["value"]
        self.assertIs(binding["instrumented"], False)
        self.assertEqual(binding["scope"], TOOL._UPDATE_DISTRIBUTION_SCOPE if update else "current-macos-candidate" if candidate else
                         "engineering-acl-probe-five-regressions-fixed-fixture-package-install-only"
                         if installed else "normal-macos-early-preview")
        self.assertFalse(binding["applicationLaunched"] or binding["fullUIQualified"] or binding["distributionQualified"])
        return binding

    def test_preview_roster_has_no_raw_evidence_and_keeps_open_and_quit_unexecuted(self):
        for target in TOOL.MAC_TARGETS:
            work, values, documents, expected, selection = self.preview_fixture(target)
            documents["source-binding.json"] = self.actual_workflow_binding(target, installed=False)
            values[work / "source-binding.json"] = TOOL.canonical(documents["source-binding.json"])
            args = SimpleNamespace(work=work, output=work / "preview", expected_source="a" * 40)
            if target != TOOL.ARM_TARGET:
                args.target = target  # The original ARM default still runs.
            with mock.patch.object(TOOL, "read", side_effect=lambda path, *_: values[path]), \
                    mock.patch.object(TOOL, "source_build_selection", return_value=selection) as selected, \
                    mock.patch.object(TOOL, "observation_inventory", return_value=expected) as inventory_read, \
                    mock.patch.object(TOOL, "write_tree") as output:
                result = TOOL.preview_command(args)
            selected.assert_called_once_with(target)
            self.assertIs(inventory_read.call_args.kwargs["selection"], selection)
            files = output.call_args.args[1]
            self.assertEqual(set(files), {"MobileReleaseKit.dmg", "README.md", "PREVIEW.json"})
            self.assertEqual(files["MobileReleaseKit.dmg"], (values[work / "distribution-final/MobileReleaseKit.dmg"], 0o444))
            self.assertNotEqual(files["MobileReleaseKit.dmg"][0], values[work / "distribution/MobileReleaseKit.dmg"])
            summary = TOOL.decode(files["PREVIEW.json"][0])
            self.assertEqual(summary["automaticWindowOpen"], "unexecuted")
            self.assertEqual(summary["normalQuit"], "unexecuted")
            self.assertEqual(summary["manualUIAcceptance"], "pending")
            self.assertFalse(summary["fullM2Qualified"] or summary["maintenanceQualified"])
            self.assertEqual(summary["ordinaryEntryRoute"], "unexecuted")
            self.assertEqual(summary["directPayloadPreMain"], "unqualified")
            self.assertEqual(summary["signedEntryBinarySha256"], "f" * 64)
            self.assertEqual(summary["packageRole"], "ordinary-image")
            self.assertEqual(summary["normalBinaryBeforeSigningSha256"], documents["app-result.json"]["appBinarySha256BeforeSigning"])
            self.assertEqual(summary["desktopImageBeforeSigningSha256"], documents["app-result.json"]["desktopImageSha256BeforeSigning"])
            self.assertNotEqual(summary["normalBinaryBeforeSigningSha256"], summary["desktopImageBeforeSigningSha256"])
            self.assertEqual((summary["signedDesktopImageSha256"], summary["signedResidentImageSha256"]), ("9" * 64, "7" * 64))
            self.assertFalse(summary["fullUIQualified"])
            self.assertFalse(summary["distributionQualified"])
            self.assertFalse(summary["productReady"])
            self.assertEqual(result["fileCount"], 3)

            self.assertTrue(summary["originalInstallerReturnedZero"] and summary["originalPackageGroupReturnedZero"]
                            and summary["originalObservationMountDetached"])
            self.assertEqual(summary["requestId"], "1" * 32)
            self.assertEqual(summary["descriptorSha256"], TOOL.digest(values[work / "producer-root/producer.json"]))
            self.assertEqual(summary["signatureSha256"], TOOL.digest(values[work / "producer-root/producer.sig"]))
            self.assertEqual(summary["platform"], "macOS26-arm64" if target == TOOL.ARM_TARGET else "macOS26-x86_64")
            self.assertTrue(summary["originalImageFinalizationReturnedZero"] and summary["originalFinalImageMountDetached"])
            self.assertTrue(summary["finalImageScopedNotarizationObserved"])
            self.assertEqual(summary["finalImageReceiptSha256"], TOOL.digest(values[work / "android-helper-finalize-image.json"]))
            self.assertEqual(summary["originalDistributionSha256"], TOOL.digest(values[work / "distribution/MobileReleaseKit.dmg"]))
            self.assertNotEqual(summary["originalDistributionSha256"], TOOL.digest(files["MobileReleaseKit.dmg"][0]))

            good_binding = copy.deepcopy(documents["source-binding.json"])
            for key, wrong in (("scope", "engineering-acl-probe-five-regressions-fixed-fixture-package-install-only"),
                               ("instrumented", None), ("instrumented", 0), ("instrumented", True)):
                binding = copy.deepcopy(good_binding)
                if wrong is None: binding.pop(key)
                else: binding[key] = wrong
                values[work / "source-binding.json"] = TOOL.canonical(binding)
                with (mock.patch.object(TOOL, "read", side_effect=lambda path, *_: values[path]),
                      mock.patch.object(TOOL, "source_build_selection", return_value=selection),
                      mock.patch.object(TOOL, "write_tree") as refused_output):
                    with self.subTest(preview_binding=target, key=key, wrong=wrong), self.assertRaisesRegex(TOOL.Refused, "^preview-source-binding$"):
                        TOOL.preview_command(args)
                    refused_output.assert_not_called()
            values[work / "source-binding.json"] = TOOL.canonical(good_binding)

        # Actual nonroot work-tree read and output write, not a mocked exporter.
        # The synthetic SOURCE profile/inventory ports remain explicit DATA;
        # none of these receipts are native qualification.
        for target in TOOL.MAC_TARGETS:
            for fault in (None, "missing-flag", "wrong-scope", "missing-instrumented", "nonbool-instrumented", "instrumented",
                          "missing-context", "wrong-ref", "wrong-source", "wrong-run", "receipt-context",
                          "unknown-close", "receipt-read", "copy-read", "collision"):
                with self.subTest(installed_carrier=target, fault=fault), tempfile.TemporaryDirectory() as directory:
                    old_work, values, documents, expected, selection = self.preview_fixture(target)
                    binding = self.actual_workflow_binding(target, installed=True)
                    if fault == "wrong-scope": binding["scope"] = "normal-macos-early-preview"
                    if fault == "missing-instrumented": binding.pop("instrumented")
                    if fault == "nonbool-instrumented": binding["instrumented"] = 0
                    if fault == "instrumented": binding["instrumented"] = True
                    documents["source-binding.json"] = binding
                    values[old_work / "source-binding.json"] = TOOL.canonical(binding)
                    work = Path(directory) / "work"; work.mkdir(mode=0o700)
                    receipt = documents["android-helper-finalize-image.json"]
                    receipt["workflow"] = TOOL._INSTALLED_FINAL_IMAGE_WORKFLOW
                    if fault == "receipt-context": receipt["workflow"] = TOOL._PREVIEW_FINAL_IMAGE_WORKFLOW
                    if fault == "unknown-close": receipt["originalClosesKnown"] = False
                    values[old_work / "android-helper-finalize-image.json"] = TOOL.canonical(receipt)
                    source_values = {}
                    for original, contents in values.items():
                        if not original.is_relative_to(old_work):
                            source_values[original] = contents
                            continue
                        path = work / original.relative_to(old_work)
                        path.parent.mkdir(mode=0o700, parents=True, exist_ok=True)
                        if path.name in ("normal-build.jsonl", "app-result.json"):
                            contents = contents.replace(str(old_work).encode(), str(work).encode())
                        path.write_bytes(contents); path.chmod(0o600)
                    binary = work / "cargo-target" / target / "release/libmrk_desktop_image.dylib"
                    documents["app-result.json"]["desktopImageCargoArtifact"] = TOOL.image_cargo_artifact(
                        (work / "normal-build.jsonl").read_bytes(), binary, work / "cargo-target",
                        binary.read_bytes(), "desktop", target=target, package_version=selection.package_version)
                    (work / "app-result.json").write_bytes(TOOL.canonical(documents["app-result.json"]))
                    env = {"GITHUB_REPOSITORY": "Apdelrahman1911/mobile-release-kit",
                        "GITHUB_REF": "refs/heads/verify/desktop-macos-installed",
                        "GITHUB_WORKFLOW_REF": TOOL._INSTALLED_FINAL_IMAGE_WORKFLOW,
                        "GITHUB_SHA": "a" * 40, "GITHUB_WORKFLOW_SHA": "a" * 40,
                        "GITHUB_RUN_ID": "123", "GITHUB_RUN_ATTEMPT": "1"}
                    if fault == "missing-context": env.pop("GITHUB_WORKFLOW_REF")
                    if fault == "wrong-ref": env["GITHUB_REF"] = "refs/heads/verify/desktop-macos-preview"
                    if fault == "wrong-source": env["GITHUB_SHA"] = "b" * 40
                    if fault == "wrong-run": env["GITHUB_RUN_ATTEMPT"] = "2"
                    output = work / "p0-carrier-input"
                    if fault == "collision": output.mkdir(mode=0o700); (output / "unrelated").write_bytes(b"preserve")
                    if fault == "receipt-read": (work / "android-helper-finalize-image.json").unlink()
                    if fault == "copy-read": (work / "distribution-final/MobileReleaseKit.dmg").unlink()
                    originals = {p: (p.read_bytes(), os.lstat(p)) for p in work.rglob("*") if p.is_file()}
                    read = TOOL.read
                    def source_port(path, *args):
                        return source_values[path] if path in source_values else read(path, *args)
                    args = TOOL.argparse.Namespace(command="preview", work=work, output=output, target=target, expected_source="a" * 40,
                                           installed_passive_carrier=fault != "missing-flag")
                    with (mock.patch.dict(os.environ, env, clear=True), mock.patch.object(TOOL, "read", side_effect=source_port),
                          mock.patch.object(TOOL, "source_build_selection", return_value=selection),
                          mock.patch.object(TOOL, "observation_inventory", return_value=expected)):
                        if fault is None:
                            result = TOOL.preview_command(args)
                            self.assertEqual(result["fileCount"], 2)
                            self.assertEqual(set(os.listdir(output)), {"MobileReleaseKit.dmg", "PREVIEW.json"})
                            self.assertEqual((output / "MobileReleaseKit.dmg").read_bytes(), values[old_work / "distribution-final/MobileReleaseKit.dmg"])
                            self.assertEqual(stat.S_IMODE(os.stat(output).st_mode), 0o555)
                            self.assertTrue(all(stat.S_IMODE(os.stat(p).st_mode) == 0o444 for p in output.iterdir()))
                            summary = TOOL.decode((output / "PREVIEW.json").read_bytes())
                            self.assertEqual(summary["finalImageReceiptSha256"], TOOL.digest(TOOL.canonical(receipt)))
                            self.assertFalse(summary["productReady"] or summary["distributionQualified"] or summary["fullUIQualified"])
                            output.chmod(0o700)  # Only this test-owned regeneration output.
                        else:
                            with self.assertRaises((TOOL.Refused, OSError)) as failed: TOOL.preview_command(args)
                            diagnostic = io.StringIO()
                            with contextlib.redirect_stderr(diagnostic): TOOL.carrier_refusal_annotation(args, failed.exception)
                            if fault == "missing-flag": self.assertEqual(diagnostic.getvalue(), "")
                            else:
                                group = ("source-binding" if fault in ("wrong-scope", "missing-instrumented", "nonbool-instrumented", "instrumented",
                                                                     "missing-context", "wrong-ref", "wrong-source", "wrong-run")
                                         else "output-write" if fault == "collision" else "final-image-copy" if fault == "copy-read"
                                         else "final-image-receipt")
                                self.assertEqual(args._carrier_validation_group, group)
                                reason = (failed.exception.args[0] if type(failed.exception) is TOOL.Refused else "other")
                                self.assertEqual(diagnostic.getvalue(), "::error title=MRK carrier refused::group=" + group + ";reason=" + reason + "\n")
                            if fault == "collision": self.assertEqual((output / "unrelated").read_bytes(), b"preserve")
                            else: self.assertFalse(output.exists())
                    for p, (contents, info) in originals.items():
                        current = os.lstat(p)
                        self.assertEqual((current.st_dev,current.st_ino,current.st_mode,current.st_uid,current.st_gid,
                                          current.st_nlink,current.st_size,current.st_mtime_ns,current.st_ctime_ns),
                                         (info.st_dev,info.st_ino,info.st_mode,info.st_uid,info.st_gid,
                                          info.st_nlink,info.st_size,info.st_mtime_ns,info.st_ctime_ns))
                        self.assertEqual(p.read_bytes(), contents)
                    with self.assertRaises(TOOL.Refused):
                        TOOL.final_image_receipt_data(b"not parsed", selection=selection, binding={}, request=None,
                            package=b"", descriptor=b"", signed=b"", original_image={}, package_owner=b"",
                            final_package=b"", release_body=b"", profiles=(), remove=True,
                            expected_workflow=TOOL._INSTALLED_FINAL_IMAGE_WORKFLOW)

    def test_candidate_carrier_is_explicit_and_never_remove_authority(self):
        cli = ["preview", "--candidate-carrier", "--work", "/inert/work", "--expected-source", "a" * 40,
               "--output", "/inert/candidate"]
        with mock.patch.object(TOOL, "preview_command", return_value={}) as action, contextlib.redirect_stdout(io.StringIO()):
            TOOL.main(cli)
        args = action.call_args.args[0]
        self.assertIs(args.candidate_carrier, True)
        self.assertIs(args.installed_passive_carrier, False)
        for refused_cli in (cli + ["--installed-passive-carrier"], ["remove-preview", *cli[1:]]):
            with (mock.patch.object(TOOL, "preview_command") as preview,
                  mock.patch.object(TOOL, "remove_preview_command") as remove,
                  contextlib.redirect_stderr(io.StringIO()), self.assertRaises(SystemExit) as stopped):
                TOOL.main(refused_cli)
            self.assertEqual(stopped.exception.code, 2)
            preview.assert_not_called(); remove.assert_not_called()
        with mock.patch.object(TOOL, "read") as read:
            with self.assertRaisesRegex(TOOL.Refused, "^preview-purpose$"):
                TOOL.remove_preview_command(args)
            for candidate, installed in ((True, True), (1, False), ("yes", False)):
                invalid = TOOL.argparse.Namespace(**{**vars(args), "candidate_carrier": candidate,
                                                    "installed_passive_carrier": installed})
                with self.assertRaisesRegex(TOOL.Refused, "^preview-purpose$"):
                    TOOL.preview_command(invalid)
            with self.assertRaisesRegex(TOOL.Refused, "^final-image-receipt-purpose$"):
                TOOL.final_image_receipt_data(b"not parsed", selection=None, binding={}, request=None,
                    package=b"", descriptor=b"", signed=b"", original_image={}, package_owner=b"",
                    final_package=b"", release_body=b"", profiles=(), remove=True,
                    expected_workflow=TOOL._CANDIDATE_FINAL_IMAGE_WORKFLOW)
            read.assert_not_called()
        primary = TOOL.Refused("candidate-carrier-ci-context")
        def refuse(parsed):
            parsed._carrier_validation_group = "source-binding"
            raise primary
        diagnostic = io.StringIO()
        with (mock.patch.object(TOOL, "preview_command", side_effect=refuse), contextlib.redirect_stderr(diagnostic),
              self.assertRaises(TOOL.Refused) as stopped):
            TOOL.main(cli)
        self.assertIs(stopped.exception, primary)
        self.assertEqual(diagnostic.getvalue(),
            "::error title=MRK carrier refused::group=source-binding;reason=candidate-carrier-ci-context\n")

    def test_update_export_shell_arguments_failure_and_cleanup_selection(self):
        # Only /bin/bash and a local printf stub run; no native tool or package.
        import subprocess
        import textwrap
        workflow = (Path(__file__).resolve().parents[2] / ".github/workflows/desktop-macos-installed.yml").read_text()
        stage = workflow_step(workflow, "Stage only the audited normal early-preview deliverables")
        script = textwrap.dedent(stage.split("        run: |\n", 1)[1])
        for target in TOOL.MAC_TARGETS:
            for route in ("preview", "positive-update"):
                for failure in (0, 17):
                    with self.subTest(target=target, route=route, failure=failure), tempfile.TemporaryDirectory(prefix="export with spaces ") as directory:
                        root = Path(directory); stub = root / "python stub"; log = root / "args"
                        stub.write_text('#!/bin/bash\nprintf "%s\\0" "$@" >> "$ARGS_LOG"\nprintf "END\\0" >> "$ARGS_LOG"\nexit "$FAILURE"\n')
                        stub.chmod(0o700)
                        result = subprocess.run(["/bin/bash", "-c", script], cwd=root, timeout=10,
                            stdout=subprocess.PIPE, stderr=subprocess.PIPE,
                            env={"PATH": "/usr/bin:/bin", "MRK_PYTHON": str(stub), "MRK_MACOS_WORK": str(root),
                                "MRK_MACOS_TARGET": target, "MRK_EXPECTED_SHA": "a" * 40,
                                "GITHUB_REF": "refs/heads/verify/desktop-macos-" + route,
                                "ARGS_LOG": str(log), "FAILURE": str(failure)})
                        self.assertEqual(result.returncode, failure, result.stderr)
                        calls = log.read_bytes().split(b"END\0")[:-1]
                        self.assertEqual(len(calls), 1 if failure else 2)
                        for command, call in zip(("preview", "remove-preview"), calls):
                            args = call.decode().rstrip("\0").split("\0")
                            expected = ["-I", "-S", "-B", "desktop/tools/stage_macos_installed.py", command]
                            if route == "positive-update": expected.append("--positive-update-carrier")
                            expected += ["--target", target, "--work", str(root), "--expected-source", "a" * 40,
                                         "--output", str(root / command)]
                            self.assertEqual(args, expected)
                        self.assertEqual(b"Matched installation/removal" in result.stdout, failure == 0)
        # Exercise only the new roster selection, never destructive cleanup or
        # a mocked native receipt. Existing path/inode/owner guards remain intact.
        cleanup = workflow_step(workflow, "Remove only this completed preview build's disposable compiler outputs")
        code = textwrap.dedent(cleanup.split("<<'PY_CLEAN'\n", 1)[1].split("          PY_CLEAN", 1)[0])
        tree = ast.parse(code)
        node = next(n for n in tree.body if isinstance(n, ast.If) and "positive-update" in ast.unparse(n.test))
        selected = compile(ast.fix_missing_locations(ast.Module(body=[node], type_ignores=[])), "<cleanup-update-selection>", "exec")
        for route, binding, expected in (("positive-update", {"scope": TOOL._UPDATE_DISTRIBUTION_SCOPE, "instrumented": False}, ("update-p0-bootstrap", "update-p1-resume")),
                ("preview", {}, ("saved-checks",)), ("positive-update", {"scope": "normal-macos-early-preview", "instrumented": False}, None),
                ("positive-update", {"scope": TOOL._UPDATE_DISTRIBUTION_SCOPE, "instrumented": True}, None)):
            namespace = {"os": SimpleNamespace(environ={"GITHUB_REF": "refs/heads/verify/desktop-macos-" + route}),
                         "binding": binding, "stems": ("saved-checks",)}
            if expected is None:
                with self.assertRaises(ValueError): exec(selected, namespace)
            else:
                exec(selected, namespace); self.assertEqual(namespace["stems"], expected)

    def test_positive_update_export_requires_current_update_and_closed_credentials(self):
        # Reuse the existing inert signed/native fixture; this tests actual exporter
        # logic, not Mac signatures, Installer, Keychain or update qualification.
        faults = (None, "wrong-ref", "wrong-event", "wrong-scope", "fixture", "mixed-mode",
                  "old-workflow", "fresh-install", "package-status", "p0-test", "p0-summary", "p1-test", "p1-summary")
        for target in TOOL.MAC_TARGETS:
            for fault in faults:
                with self.subTest(target=target, fault=fault):
                    work, values, documents, inventory, selection = self.preview_fixture(target)
                    documents["source-binding.json"] = self.actual_workflow_binding(target, installed=False, update=True)
                    observed = documents["installation-observation.json"]
                    observed["originalInstallerResult"]["action"] = "fresh-install" if fault == "fresh-install" else "update"
                    documents["android-helper-finalize-image.json"]["workflow"] = (
                        TOOL._PREVIEW_FINAL_IMAGE_WORKFLOW if fault == "old-workflow" else TOOL._UPDATE_FINAL_IMAGE_WORKFLOW)
                    if fault == "wrong-scope": documents["source-binding.json"]["scope"] = "normal-macos-early-preview"
                    if fault == "fixture": documents["source-binding.json"]["instrumented"] = True
                    values.update({work / name: TOOL.canonical(value) for name, value in documents.items()})
                    if fault == "package-status": values[work / "package-install.status"] = b"1\n"
                    for segment in ("p0-bootstrap", "p1-resume"):
                        for phase in ("test", "summary"):
                            bad = fault == segment[:2] + "-" + phase
                            values[work / "normal-ui" / ("update-" + segment + "-" + phase + ".status")] = b"1\n" if bad else b"0\n"
                    env = {"GITHUB_REPOSITORY": "Apdelrahman1911/mobile-release-kit", "GITHUB_EVENT_NAME": "push",
                        "GITHUB_REF": "refs/heads/verify/desktop-macos-positive-update",
                        "GITHUB_WORKFLOW_REF": TOOL._UPDATE_FINAL_IMAGE_WORKFLOW,
                        "GITHUB_SHA": "a" * 40, "GITHUB_WORKFLOW_SHA": "a" * 40,
                        "GITHUB_RUN_ID": "123", "GITHUB_RUN_ATTEMPT": "1"}
                    if fault == "wrong-ref": env["GITHUB_REF"] = "refs/heads/verify/desktop-macos-preview"
                    if fault == "wrong-event": env["GITHUB_EVENT_NAME"] = "workflow_dispatch"
                    args = SimpleNamespace(target=target, work=work, output=work / "preview", expected_source="a" * 40,
                                           positive_update_carrier=True, candidate_carrier=fault == "mixed-mode")
                    with (mock.patch.dict(os.environ, env, clear=True),
                          mock.patch.object(TOOL, "read", side_effect=lambda path, *_: values[path]),
                          mock.patch.object(TOOL, "source_build_selection", return_value=selection),
                          mock.patch.object(TOOL, "observation_inventory", return_value=inventory),
                          mock.patch.object(TOOL, "write_tree") as output):
                        if fault is None:
                            result = TOOL.preview_command(args)
                            files = output.call_args.args[1]
                            self.assertEqual(set(files), {"MobileReleaseKit.dmg", "PREVIEW.json", "README.md"})
                            summary = TOOL.decode(files["PREVIEW.json"][0])
                            self.assertEqual((summary["scope"], summary["workflowRef"]),
                                             (TOOL._UPDATE_DISTRIBUTION_SCOPE, TOOL._UPDATE_FINAL_IMAGE_WORKFLOW))
                            self.assertFalse(summary["productReady"] or summary["distributionQualified"] or summary["fullUIQualified"])
                            self.assertEqual(result["qualification"], "positive-update-carrier-not-product-qualified")
                        else:
                            with self.assertRaises(TOOL.Refused): TOOL.preview_command(args)
                            output.assert_not_called()
        # Real argparse selection: explicit mode reaches both existing exporters;
        # mixed candidate/update mode is rejected before an exporter is invoked.
        for command, method in (("preview", "preview_command"), ("remove-preview", "remove_preview_command")):
            argv = [command, "--positive-update-carrier", "--work", "/inert/work", "--expected-source", "a" * 40,
                    "--output", "/inert/output"]
            with mock.patch.object(TOOL, method, return_value={}) as action, contextlib.redirect_stdout(io.StringIO()):
                TOOL.main(argv)
                self.assertIs(action.call_args.args[0].positive_update_carrier, True)
            if command == "preview":
                with mock.patch.object(TOOL, method) as action, contextlib.redirect_stderr(io.StringIO()):
                    with self.assertRaises(SystemExit): TOOL.main(argv + ["--candidate-carrier"])
                    action.assert_not_called()

    def test_candidate_carrier_checks_actual_workflow_and_original_final_image(self):
        # Real bounded original reads/fresh writes. SOURCE/native observations are
        # deliberately inert DATA ports, not signature, Installer or UI evidence.
        faults = (None, "legacy-purpose", "wrong-scope", "wrong-role", "wrong-event", "wrong-ref", "wrong-attempt",
                  "receipt-workflow", "unknown-close", "unknown-native", "install-status", "final-status",
                  "changed-package", "changed-final-receipt", "changed-final-image", "collision")
        for target in TOOL.MAC_TARGETS:
            for fault in faults:
                with self.subTest(target=target, fault=fault), tempfile.TemporaryDirectory() as directory:
                    old_work, values, documents, expected, selection = self.preview_fixture(target)
                    binding = self.actual_workflow_binding(target, installed=False, candidate=True)
                    if fault == "wrong-scope": binding["scope"] = "normal-macos-early-preview"
                    if fault == "wrong-role": binding["packageRole"] = "installed-shell-observation"
                    documents["source-binding.json"] = binding
                    receipt = documents["android-helper-finalize-image.json"]
                    receipt["workflow"] = TOOL._CANDIDATE_FINAL_IMAGE_WORKFLOW
                    if fault == "receipt-workflow": receipt["workflow"] = TOOL._PREVIEW_FINAL_IMAGE_WORKFLOW
                    if fault == "unknown-close": receipt["originalClosesKnown"] = False
                    if fault == "unknown-native": receipt["originalCalls"][0]["returned"] = False
                    values.update({old_work / name: TOOL.canonical(value) for name, value in documents.items()})
                    mutations = {"install-status": "package-install.status", "final-status": "image-finalization.status",
                        "changed-package": "package-final/MobileReleaseKit.pkg",
                        "changed-final-receipt": "android-helper-finalize-package.json",
                        "changed-final-image": "distribution-final/MobileReleaseKit.dmg"}
                    if fault in mutations: values[old_work / mutations[fault]] = b"changed\n"
                    work = Path(directory) / "work"; work.mkdir(mode=0o700)
                    source_values = {}
                    for original, contents in values.items():
                        if not original.is_relative_to(old_work):
                            source_values[original] = contents
                            continue
                        path = work / original.relative_to(old_work)
                        path.parent.mkdir(mode=0o700, parents=True, exist_ok=True)
                        if path.name in ("normal-build.jsonl", "app-result.json"):
                            contents = contents.replace(str(old_work).encode(), str(work).encode())
                        path.write_bytes(contents); path.chmod(0o600)
                    binary = work / "cargo-target" / target / "release/libmrk_desktop_image.dylib"
                    documents["app-result.json"]["desktopImageCargoArtifact"] = TOOL.image_cargo_artifact(
                        (work / "normal-build.jsonl").read_bytes(), binary, work / "cargo-target", binary.read_bytes(),
                        "desktop", target=target, package_version=selection.package_version)
                    (work / "app-result.json").write_bytes(TOOL.canonical(documents["app-result.json"]))
                    env = {"GITHUB_REPOSITORY": "Apdelrahman1911/mobile-release-kit", "GITHUB_EVENT_NAME": "push",
                        "GITHUB_REF": "refs/heads/verify/desktop-macos-candidate",
                        "GITHUB_WORKFLOW_REF": TOOL._CANDIDATE_FINAL_IMAGE_WORKFLOW,
                        "GITHUB_SHA": "a" * 40, "GITHUB_WORKFLOW_SHA": "a" * 40,
                        "GITHUB_RUN_ID": "123", "GITHUB_RUN_ATTEMPT": "1"}
                    if fault == "wrong-event": env["GITHUB_EVENT_NAME"] = "workflow_dispatch"
                    if fault == "wrong-ref": env["GITHUB_REF"] = "refs/heads/verify/desktop-macos-preview"
                    if fault == "wrong-attempt": env["GITHUB_RUN_ATTEMPT"] = "2"
                    output = work / "candidate"
                    if fault == "collision": output.mkdir(mode=0o700); (output / "foreign").write_bytes(b"preserve")
                    originals = {p: (p.read_bytes(), os.lstat(p)) for p in work.rglob("*") if p.is_file()}
                    args = TOOL.argparse.Namespace(command="preview", work=work, output=output, target=target,
                        expected_source="a" * 40, candidate_carrier=fault != "legacy-purpose")
                    original_read = TOOL.read
                    def read_source(path, *args):
                        return source_values[path] if path in source_values else original_read(path, *args)
                    with (mock.patch.dict(os.environ, env, clear=True), mock.patch.object(TOOL, "read", side_effect=read_source),
                          mock.patch.object(TOOL, "source_build_selection", return_value=selection),
                          mock.patch.object(TOOL, "observation_inventory", return_value=expected)):
                        if fault is None:
                            result = TOOL.preview_command(args)
                            self.assertEqual(result["qualification"], "current-candidate-not-consumer-or-product-qualified")
                            self.assertEqual(set(os.listdir(output)), {"MobileReleaseKit.dmg", "PREVIEW.json", "README.md"})
                            self.assertEqual((output / "MobileReleaseKit.dmg").read_bytes(),
                                             values[old_work / "distribution-final/MobileReleaseKit.dmg"])
                            summary = TOOL.decode((output / "PREVIEW.json").read_bytes())
                            self.assertEqual(summary["scope"], "current-macos-candidate")
                            self.assertEqual(summary["workflowRef"], TOOL._CANDIDATE_FINAL_IMAGE_WORKFLOW)
                            self.assertEqual(summary["finalImageReceiptSha256"], TOOL.digest(TOOL.canonical(receipt)))
                            self.assertEqual((summary["automaticWindowOpen"], summary["normalQuit"]), ("unexecuted", "unexecuted"))
                            self.assertFalse(summary["fullUIQualified"] or summary["productReady"] or summary["distributionQualified"])
                            guide = (output / "README.md").read_bytes()
                            self.assertEqual(guide, TOOL._CANDIDATE_GUIDE)
                            self.assertIn(b"NOT READY", guide); self.assertIn(b"No Remove carrier", guide)
                            self.assertEqual(stat.S_IMODE(os.stat(output).st_mode), 0o555)
                            self.assertTrue(all(stat.S_IMODE(os.stat(p).st_mode) == 0o444 for p in output.iterdir()))
                            output.chmod(0o700)  # Only the fixture's own sealed output, for disposal.
                        else:
                            with self.assertRaises((TOOL.Refused, OSError)): TOOL.preview_command(args)
                            if fault == "collision": self.assertEqual((output / "foreign").read_bytes(), b"preserve")
                            else: self.assertFalse(output.exists())
                    for path, (body, before) in originals.items():
                        after = os.lstat(path)
                        for field in ("st_dev", "st_ino", "st_mode", "st_uid", "st_gid", "st_nlink", "st_size", "st_mtime_ns", "st_ctime_ns"):
                            self.assertEqual(getattr(after, field), getattr(before, field))
                        self.assertEqual(path.read_bytes(), body)

